import unittest

class Behavior(unittest.TestCase):
    def test_contract(self):
        from restore import original_name
        for name, expected in [('cab.bak','cab'), ('report.bak','report'), ('oak','oak'),
                               ('a.bak.bak','a.bak'), ('.bak',''), ('',''),
                               ('notes.BAK','notes.BAK'), ('x.bak.tmp','x.bak.tmp'),
                               ('资料.bak','资料')]:
            with self.subTest(name=name):
                self.assertEqual(original_name(name), expected)

if __name__ == "__main__":
    unittest.main()
